  "implementation": "def solve(case):
    nodes = case['nodes']
    core_dist = case['core_distance']
    distances = case['distances']
    edges = []
    for u, v, d in distances:
        w = max(core_dist[u], core_dist[v], d)
        if u > v:
            u, v = v, u
        edges.append((w, u, v))
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx = find(x)
        ry = find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total = 0.0
    selected = 0
    target = len(nodes) - 1
    for w, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total += w
            selected += 1
            if selected == target:
                break
    return {"mst_edges": mst_edges, "total_weight": total}
